  'jwt verify (hs256)': { name: 'JWT verify (HS256)', cat: 'dev', inputs: [{ key: 'secret', label: 'Secret', type: 'text' }], run: async (t, c) => {
    const parts = String(t).trim().split('.'); if (parts.length !== 3) throw Error('Not a JWT (expected 3 dot-separated parts)');
    const b64u = (s) => Uint8Array.from(atob(s.replace(/-/g, '+').replace(/_/g, '/')), (x) => x.charCodeAt(0));
    const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(String(c.secret || '')), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
    const sig = await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(parts[0] + '.' + parts[1]));
    const expected = btoa(String.fromCharCode(...new Uint8Array(sig))).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
    const header = JSON.parse(new TextDecoder().decode(b64u(parts[0]))), payload = JSON.parse(new TextDecoder().decode(b64u(parts[1])));
    return JSON.stringify({ valid: expected === parts[2], header, payload, exp: payload.exp ? new Date(payload.exp * 1000).toISOString() : undefined }, null, 2); } },
